# =============================================================================
# Chapter 12 values: Time Series Analysis
#
# Run from the project root:
#   Rscript r_code/figures/chapter_12_values.R
#
# The figures are generated by r_code/figures/chapter_12.R. This script records
# the values behind the prose and the exercises. The main analysis uses the
# weekly gym_membership_searches.csv file. The exercise values use the monthly
# sunscreen_searches.csv file. The author's reference calculations are in
# r_code/chapter_12.r; this script reproduces them and records the conventions.
# figures/chapter_12/values.yml is generated by save_book_values(); do not edit
# it by hand.
# =============================================================================

source("r_code/figures/_book_figs.R")

suppressPackageStartupMessages({
  library(dplyr)
  library(readr)
  library(lubridate)
  library(forecast)
})

# ---- Data -------------------------------------------------------------------

gym <- read_csv("data/gym_membership_searches.csv", show_col_types = FALSE) %>%
  mutate(Week = mdy(Week)) %>%
  rename(search_index = `gym membership`) %>%
  arrange(Week) %>%
  mutate(lag_index = lag(search_index))

sunscreen <- read_csv("data/sunscreen_searches.csv", show_col_types = FALSE) %>%
  mutate(Month = mdy(Month)) %>%
  arrange(Month) %>%
  mutate(lag_index = lag(sunscreen))

# ---- Gym models -------------------------------------------------------------

gym_peak <- gym %>% slice_max(search_index, n = 1, with_ties = FALSE)

gym_cor <- cor(
  gym$search_index, gym$lag_index, use = "complete.obs"
)
gym_slope <- unname(coef(
  lm(search_index ~ lag_index, data = gym)
)[2])

gym_trend <- lm(search_index ~ as.numeric(Week), data = gym)
gym_trend_coef <- summary(gym_trend)$coefficients

winter_peaks <- gym %>%
  filter(month(Week) %in% c(11, 12, 1, 2)) %>%
  mutate(
    season = if_else(month(Week) >= 11, year(Week) + 1L, year(Week))
  ) %>%
  group_by(season) %>%
  summarise(peak = max(search_index), .groups = "drop")

gym_ts <- ts(gym$search_index, frequency = 52, start = c(2021, 20))
gym_arima <- auto.arima(gym_ts)
gym_forecast <- forecast(gym_arima, h = 52)
gym_forecast_peak <- max(gym_forecast$mean)
gym_forecast_peak_date <- max(gym$Week) + 7 * which.max(gym_forecast$mean)

# ---- Sunscreen models -------------------------------------------------------

sunscreen_peak <- sunscreen %>%
  slice_max(sunscreen, n = 1, with_ties = FALSE)

sunscreen_cor <- cor(
  sunscreen$sunscreen, sunscreen$lag_index, use = "complete.obs"
)
sunscreen_slope <- unname(coef(
  lm(sunscreen ~ lag_index, data = sunscreen)
)[2])

sunscreen_ts <- ts(
  sunscreen$sunscreen, frequency = 12, start = c(2021, 10)
)
sunscreen_arima <- auto.arima(sunscreen_ts)
sunscreen_forecast <- forecast(sunscreen_arima, h = 12)
sunscreen_forecast_peak <- max(sunscreen_forecast$mean)
sunscreen_peak_month <- month.abb[
  cycle(sunscreen_forecast$mean)[which.max(sunscreen_forecast$mean)]
]

# ---- Values registry --------------------------------------------------------

values <- list(
  data = list(
    gym_file = "gym_membership_searches.csv",
    gym_rows = nrow(gym),
    gym_start = as.character(min(gym$Week)),
    gym_end = as.character(max(gym$Week)),
    gym_columns = "Week, gym membership",
    sunscreen_file = "sunscreen_searches.csv",
    sunscreen_rows = nrow(sunscreen),
    sunscreen_start = as.character(min(sunscreen$Month)),
    sunscreen_end = as.character(max(sunscreen$Month)),
    sunscreen_columns = "Month, sunscreen",
    note = paste(
      "The gym file is the restored 262-row weekly data from commit",
      "cc3e3a4, covering May 2021 through May 2026. The sunscreen file is",
      "the 61-row monthly data from the October 2026 Google Trends export,",
      "covering October 2021 through October 2026. Google Trends now reports",
      "the sunscreen term monthly, so the two series have different time",
      "steps."
    )
  ),
  gym_time_series = list(
    n = nrow(gym),
    peak_value = gym_peak$search_index,
    peak_date = as.character(gym_peak$Week),
    winter_peaks = as.list(setNames(winter_peaks$peak, winter_peaks$season)),
    note = paste(
      "The winter peaks are 37 in the season ending 2022, 48 in 2023, 54",
      "in 2024, 64 in 2025, and 100 in 2026, so the winter spikes grow over",
      "time. A season runs from November through February and is labeled by",
      "the year of its January and February. The 2026 peak is the maximum",
      "index value and falls on 2026-02-15."
    )
  ),
  gym_autocorrelation = list(
    lag = 1,
    pairs = sum(!is.na(gym$lag_index)),
    r = round(gym_cor, 4),
    slope = round(gym_slope, 4),
    note = paste(
      "Lag-1 Pearson correlation uses 261 complete pairs; the first week",
      "has no previous value. The chapter rounds r to 0.92 and the slope to",
      "0.93. The fitted slope is current week on previous week."
    )
  ),
  gym_linear_trend = list(
    model = "lm(gym membership ~ as.numeric(Week))",
    slope_per_week = round(gym_trend_coef[2, 1], 4),
    p = gym_trend_coef[2, 4],
    r_squared = round(summary(gym_trend)$r.squared, 4),
    note = paste(
      "This is the naive trend model the chapter warns against. Its",
      "p-value is not valid because the residuals are autocorrelated; the",
      "chapter uses it only to explain why standard regression is",
      "overconfident on time series data."
    )
  ),
  gym_arima = list(
    model = paste(
      "auto.arima(ts(gym membership, frequency = 52,",
      "start = c(2021, 20)))"
    ),
    order = "ARIMA(1,1,1)(0,0,1)[52]",
    coefficients = as.list(round(coef(gym_arima), 4)),
    forecast_h = 52,
    forecast_peak = round(gym_forecast_peak, 1),
    forecast_peak_date = as.character(gym_forecast_peak_date),
    interval_width_first = round(
      gym_forecast$upper[1, 2] - gym_forecast$lower[1, 2], 1
    ),
    interval_width_last = round(
      gym_forecast$upper[52, 2] - gym_forecast$lower[52, 2], 1
    ),
    note = paste(
      "The model is selected by auto.arima on the weekly series. The",
      "52-week forecast peaks at 70.3 on 2027-02-14, below the 2026 record",
      "of 100. The 95% prediction interval widens from 18.7 points in the",
      "first forecast week to 44.7 points in the last. The chapter calls",
      "this a typical winter peak, not an average."
    )
  ),
  sunscreen_seasonality = list(
    peak_value = sunscreen_peak$sunscreen,
    peak_month = as.character(sunscreen_peak$Month),
    note = paste(
      "Sunscreen peaks in late spring and early summer. In 2026 the values",
      "are 91 in April, 87 in May, and 100 in June, so the exercise answer",
      "is a spring-to-summer peak rather than a winter peak."
    )
  ),
  sunscreen_autocorrelation = list(
    lag = 1,
    pairs = sum(!is.na(sunscreen$lag_index)),
    r = round(sunscreen_cor, 4),
    slope = round(sunscreen_slope, 4),
    note = paste(
      "Monthly lag-1 correlation for exercise 11, using 60 complete pairs.",
      "The first month has no previous value."
    )
  ),
  sunscreen_arima = list(
    model = paste(
      "auto.arima(ts(sunscreen, frequency = 12,",
      "start = c(2021, 10)))"
    ),
    order = "ARIMA(0,1,0)(1,1,0)[12]",
    coefficients = as.list(round(coef(sunscreen_arima), 4)),
    forecast_h = 12,
    forecast_peak = round(sunscreen_forecast_peak, 1),
    forecast_peak_month = paste(sunscreen_peak_month, 2027),
    note = paste(
      "The 12-month forecast for exercise 12 peaks in June 2027 at 83.0.",
      "The monthly series is shorter than the weekly gym series, so the",
      "exercise forecast is 12 months, not 52 weeks."
    )
  ),
  table_12_1 = list(
    note = "Notation table; no calculated values."
  ),
  figures = list(
    figure_12_1 = list(
      note = paste(
        "Weekly time series, 262 points. Winter peaks grow from 31 to 100;",
        "the 2026 peak is marked."
      )
    ),
    figure_12_2 = list(
      note = paste(
        "Lag-1 scatterplot with 261 pairs. r = 0.92 and the fitted slope is",
        "0.93; the dashed line is the least-squares fit."
      )
    ),
    figure_12_3 = list(
      note = paste(
        "52-week ARIMA forecast. The dashed forecast peaks at 70.3 in",
        "February 2027, below the 2026 record of 100; the shaded 95%",
        "prediction interval widens through the forecast."
      )
    )
  )
)

save_book_values(
  chapter = 12,
  values = values,
  conventions = list(
    data = paste(
      "Two files at their true frequencies. gym_membership_searches.csv is",
      "weekly: 262 rows, Week and gym membership, May 2021 through May 2026.",
      "sunscreen_searches.csv is monthly: 61 rows, Month and sunscreen,",
      "October 2021 through October 2026. Dates are stored as MM-DD-YY."
    ),
    autocorrelation = paste(
      "Lag-1 correlation is Pearson r between the current value and the",
      "previous value. The first observation has no lag, so the gym analysis",
      "uses 261 pairs and the sunscreen exercise uses 60 pairs."
    ),
    regression = paste(
      "The naive linear trend uses as.numeric(Week) as the predictor. Its",
      "p-value is reported only to show the overconfidence that",
      "autocorrelation creates; it is not a valid inference."
    ),
    arima = paste(
      "Models are selected by forecast::auto.arima. The gym series uses",
      "frequency 52 and start c(2021, 20), with a 52-week forecast. The",
      "sunscreen series uses frequency 12 and start c(2021, 10), with a",
      "12-month forecast. Prediction intervals are 95%."
    ),
    forecast_wording = paste(
      "The gym forecast peak is 70.3, below the 2026 record of 100. The",
      "chapter calls it a typical winter peak rather than an average height,",
      "because the historical peaks are growing and an average would be",
      "misleading."
    ),
    software_differences = paste(
      "auto.arima may select a different model if the forecast package or",
      "the data changes. The recorded model and forecast values come from",
      "the restored weekly file and the October 2026 monthly sunscreen file."
    )
  ),
  source = "r_code/figures/chapter_12_values.R"
)

# ---- Console summary --------------------------------------------------------

cat("\n--- Chapter 12 summary ---\n")
cat("Gym rows:", nrow(gym), " range:", as.character(min(gym$Week)),
    "to", as.character(max(gym$Week)), "\n")
cat("Gym peak:", gym_peak$search_index, "on", as.character(gym_peak$Week),
    "\n")
cat("Gym lag-1 r:", round(gym_cor, 4), " slope:", round(gym_slope, 4),
    " pairs:", sum(!is.na(gym$lag_index)), "\n")
cat("Gym trend p:", gym_trend_coef[2, 4], "\n")
cat("Gym ARIMA:", paste(arimaorder(gym_arima), collapse = " "), "\n")
cat("Gym forecast peak:", round(gym_forecast_peak, 1), "on",
    as.character(gym_forecast_peak_date), "\n")
cat("Sunscreen rows:", nrow(sunscreen), " range:",
    as.character(min(sunscreen$Month)), "to",
    as.character(max(sunscreen$Month)), "\n")
cat("Sunscreen lag-1 r:", round(sunscreen_cor, 4),
    " slope:", round(sunscreen_slope, 4),
    " pairs:", sum(!is.na(sunscreen$lag_index)), "\n")
cat("Sunscreen ARIMA:", paste(arimaorder(sunscreen_arima), collapse = " "),
    "\n")
cat("Sunscreen forecast peak:", round(sunscreen_forecast_peak, 1), "in",
    sunscreen_peak_month, "\n")
